from typing import List, Optional
from pydantic import BaseModel, Field


class ImagePromptResult(BaseModel):
    """The structured image prompts generated by the Image Prompt Agent."""
    hero_banner: str = Field(description="Diffusion prompt for the primary high-resolution hero image.")
    website_banner: str = Field(description="Diffusion prompt for wide landscape website banners.")
    course_thumbnail: str = Field(description="Diffusion prompt for clean, focused course thumbnail covers.")
    instagram_creative: str = Field(description="Diffusion prompt for square social media creative cards.")
    poster: str = Field(description="Diffusion prompt for high-contrast printable student posters.")
    lifestyle_image: str = Field(description="Diffusion prompt showing kids interacting naturally with STEM kits.")
    social_media_ads: str = Field(description="Diffusion prompt optimized for conversion-focused ads grids.")


class ImagePromptResponse(BaseModel):
    """Structured response wrap returned by the Image Prompt Agent."""
    status: str = Field(description="Result of execution: 'success' or 'failed'.")
    errors: List[str] = Field(default_factory=list, description="List of processing error messages.")
    prompts: Optional[ImagePromptResult] = Field(default=None, description="The validated structured prompts.")
